{
	/**
	 * Player x position
	 */
	public int x;
	/**
	 * Player y position
	 */
	public int y;
	/**
	 * Player plane
	 */
	public int plane;
	/**
	 * Player world
	 */
	public int world;
	/**
	 * Client game state
	 */
