		{
			UUID uuid = (UUID) kryo.getSerializer(UUID.class).read(kryo, input, UUID.class);
			byte[] data = (byte[]) kryo.getSerializer(byte[].class).read(kryo, input, byte[].class);
			return new S2CMicPacket(uuid, data, input.readInt());
